export const copyFor = {
    chapterResolved: (numeral) => `Chapter ${numeral} resolved.`,
    regime: (regime) => `Spring is ${regime}.`,
    ruleResults: (classified) => `${classified} of 12 specimens classified.`,
    heldOut: (accuracy) => `Held-out accuracy ${accuracy}%.`,
    trained: (accuracy, epochs) => `Training finished. Held-out accuracy ${accuracy}% after ${epochs} epochs.`,
    neighbours: (word, context, words) => context ? `Nearest to ${word} near ${context}: ${words.join(", ")}.` : `Nearest to ${word}: ${words.join(", ")}.`,
    searchCount: (count, query) => (count === 1 ? `1 result for "${query}".` : `${count} results for "${query}".`),
    nothingMatches: (query) => `Nothing in the archive matches "${query}".`,
    bookmarked: (title) => `Bookmarked ${title}.`,
    signedIn: (name) => `Signed in as ${name}.`,
    booked: (seats, title) => (seats === 1 ? `Booked 1 seat for ${title}.` : `Booked ${seats} seats for ${title}.`),
    confirmation: (title, datetime, ticket) => `${title}, ${datetime}. Ticket ${ticket}.`,
    donationReceived: (price) => `Donation of ${price} received.`,
    welcome: (tierName) => `Welcome, ${tierName} supporter.`,
    upgraded: (tierName) => `You're now a ${tierName} supporter.`,
    downgradePending: (tierName, date) => `Your change to ${tierName} is pending until ${date}.`,
    endsOn: (date) => `Your membership ends on ${date}.`,
    changesTo: (tierName, date) => `Changes to ${tierName} on ${date}.`,
    membershipEnds: (date) => `Ends on ${date}.`,
    overdue: (price) => `Payment of ${price} is overdue.`,
    nextPayment: (price, date) => `Next payment ${price} on ${date}.`,
    planPrice: (price) => `${price} a month`,
    bookingPrice: (price, seats) => `${price} for ${seats} seats`,
    seatsLeft: (n) => (n === 1 ? "1 seat left" : `${n} seats left`),
    seatPrice: (price) => `${price} a seat`,
    scheduledChange: (date, price) => `From ${date}: ${price} a month`,
    currencyLocked: (currency) => `Your supporter account pays in ${currency}. Choose ${currency} to continue.`,
    sameTier: (tierName) => `You're already on the ${tierName} tier.`,
    donationBounds: (min, max, currency) => `Enter an amount between ${formatPrice(min, currency)} and ${formatPrice(max, currency)}.`,
    moved: (label) => `Moved to ${label}.`,
    illegalTransition: (label) => `That move isn't allowed from ${label}.`,
    uploading: (file) => `Uploading ${file}.`,
    uploaded: (file) => `Upload complete: ${file}.`,
    sessionCancelled: (refunds) => `Session cancelled. ${refunds} bookings refunded.`,
    refundIssued: (price) => `Refund of ${price} issued.`,
    refundCap: (price) => `Refund can't exceed ${price}.`,
    priceScheduled: (date) => `New price scheduled from ${date}.`,
    difference: (price) => `Difference ${price}`,
};
